#!/usr/bin/env node
/**
 * apply-release-signing.mjs — Phase E release plumbing for Agents World.
 *
 * The native android/ project is GENERATED by `npx cap add android` (it is not
 * committed), so release signing cannot live in a checked-in build.gradle.
 * This script patches the generated project at build time:
 *
 *   1. android/variables.gradle — raises compileSdkVersion / targetSdkVersion
 *      to AW_TARGET_SDK (default 36). Google Play has required new apps to
 *      target API 36 (Android 16) since 2026-08-31; the Capacitor 7 template
 *      still generates 35.
 *   2. android/app/build.gradle — appends a clearly-marked `android {}` block
 *      wiring the release signing config and the versionCode/versionName to
 *      environment variables (populated from GitHub Secrets by the workflow).
 *      Appending a second `android {}` block is deliberate: Gradle merges it
 *      into the same extension, and assignment order makes these values win
 *      over the template defaults without fragile in-place edits.
 *
 * No secret value is read, printed, or written by this script — it only writes
 * references to environment variable NAMES into the generated build file.
 *
 * Run from deploy/ AFTER `npx cap add android` and `npx cap sync android`:
 *   node scripts/apply-release-signing.mjs
 *
 * Env:
 *   AW_TARGET_SDK   target/compile SDK to stamp (default "36")
 */
import { readFileSync, writeFileSync } from "node:fs";

const TARGET_SDK = process.env.AW_TARGET_SDK || "36";
const MARKER = "agents-world release signing — appended by deploy/scripts";

function fail(msg) {
  console.error(`::error::apply-release-signing: ${msg}`);
  process.exit(1);
}

// --- 1. variables.gradle: SDK levels ---------------------------------------
const varsPath = "android/variables.gradle";
let vars = readFileSync(varsPath, "utf8");
for (const key of ["compileSdkVersion", "targetSdkVersion"]) {
  const re = new RegExp(`(${key}\\s*=\\s*)\\d+`);
  if (!re.test(vars)) fail(`${key} not found in ${varsPath} — Capacitor template changed?`);
  vars = vars.replace(re, `$1${TARGET_SDK}`);
}
writeFileSync(varsPath, vars);
console.log(`variables.gradle: compile/target SDK set to ${TARGET_SDK}`);

// --- 2. app/build.gradle: signing + versioning from env --------------------
const gradlePath = "android/app/build.gradle";
const gradle = readFileSync(gradlePath, "utf8");
if (gradle.includes(MARKER)) {
  fail(`${gradlePath} already carries the release signing block — refusing to apply twice`);
}

const block = `
// >>> ${MARKER} apply-release-signing.mjs
// Release signing + versioning are read from the environment at build time
// (GitHub Secrets in CI). No secret value lives in this repo or this file.
//   AW_KEYSTORE_PATH      absolute path to the release keystore file
//   AW_KEYSTORE_PASSWORD  keystore password            (secret)
//   AW_KEY_ALIAS          key alias (default: agents-world-release)
//   AW_KEY_PASSWORD       key password                 (secret)
//   AW_VERSION_CODE       Play versionCode (workflow: 100000 + run number)
//   AW_VERSION_NAME       Play versionName (workflow input, default 1.0.0)
android {
    signingConfigs {
        release {
            storeFile file(System.getenv("AW_KEYSTORE_PATH"))
            storePassword System.getenv("AW_KEYSTORE_PASSWORD")
            keyAlias System.getenv("AW_KEY_ALIAS") ?: "agents-world-release"
            keyPassword System.getenv("AW_KEY_PASSWORD")
        }
    }
    buildTypes {
        release {
            signingConfig signingConfigs.release
        }
    }
    defaultConfig {
        versionCode Integer.parseInt(System.getenv("AW_VERSION_CODE") ?: "1")
        versionName System.getenv("AW_VERSION_NAME") ?: "1.0.0"
    }
}
// <<< agents-world release signing
`;
writeFileSync(gradlePath, gradle + block);
console.log("app/build.gradle: release signing block appended");
